#!/usr/bin/env node
// code_boss setup window - build 2739. Generated by scripts/build.mjs.
// Run it: node code-boss-setup-update.mjs - it makes the desktop shortcut "Code Boss Setup" and opens
// the window: the project folder (started once from the setup file this box has), a box to paste chunks into, each one
// committed and pushed; releases are the release window's (scripts/release-window.mjs in the project folder).
const BUILD_VERSION = '2739';

import { readFileSync, writeFileSync, existsSync, mkdirSync, rmSync, copyFileSync, renameSync, statSync, readdirSync, rmdirSync, appendFileSync } from 'node:fs';
import { spawnSync, spawn } from 'node:child_process';
import { createHash, randomBytes } from 'node:crypto';
import { homedir } from 'node:os';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import zlib from 'node:zlib';
import http from 'node:http';

// ====== src/setup-sync.mjs ======
// setup-sync.mjs - A PROJECT FOLDER KEPT UP WITH THIS ONE, A CHUNK AT A TIME: plain-text changes, each with the folder's
// hash before and after, made until the two folders are the same; the whole project, tests and documentation too.
//
// scripts/make-chunk.mjs keeps a mirror of the folder and writes each chunk from it. The setup window
// (src/setup-update-ui.mjs) keeps the project folder: started once from a setup file,
// each chunk checked - the folder's hash, and each file it touches - before anything is written, and the folder's
// hash checked against the chunk's "after" before it is. A folder keeps a record of its files (.cb-sync.json): what
// is not in it (a build's output) is not the project's.
//
// Hashes are of the text with CRLF read as LF (two copies may differ only in line ends, and a script reads
// the same either way); piishape's packed word list is read unpacked, one word to a line, so a chunk carries only the
// words that changed.

const SP_BINARY_RE = /\.(ico|png|jpe?g|gif|jar|class|zip|gz|exe|dll|woff2?|ttf)$/i;
/** True for a file whose bytes are compared and replaced whole. */
// (and text that would not come through as text: a bare CR - a chunk's lines are read with CRLF as LF, so its check
// failed - or bytes that are not UTF-8, which came out as U+FFFD with the hash still matching: both go as their bytes)
function spIsBinary(rel, buf) {
  if (SP_BINARY_RE.test(rel)) return true;
  if (!buf || !buf.length) return false;
  if (buf.includes(0)) return true;
  const t = buf.toString('utf8');
  return /\r(?!\n)/.test(t) || !Buffer.from(t, 'utf8').equals(buf);
}
/** A file's hash: its bytes when binary, its text with CRLF read as LF otherwise (a packed word list, unpacked). */
function spHash(rel, buf) {
  const h = createHash('sha256');
  h.update(spIsBinary(rel, buf) ? buf : Buffer.from(spTextOf(rel, buf), 'utf8'));
  return h.digest('hex').slice(0, 24);
}

// A PACKED WORD LIST IS DIFFED UNPACKED (the developer, 2026-11-02: "wouldn't we do a diff and just send the changed
// words?"). piishape's lexicon is one brotli blob (scripts/build-piishape-plugin.mjs), and one new word changes every
// byte of it. So the file is read with the blob unpacked - one word to a line - for the hash and the edits, and packed
// again after them. The bytes packed in another copy may differ; the words are what is checked.
const SP_LEX_FILE_RE = /^examples\/plugins\/piishape__\d+\.mjs$/;
const SP_LEX_OPEN = "const LEXICON_PACKED = ''\n";
const SP_LEX_MARK = '//@lexicon-unpacked';
/** The file's text with LF line ends, its packed word list unpacked. */
function spTextOf(rel, buf) {
  const text = buf.toString('utf8').replace(/\r\n/g, '\n');
  if (!SP_LEX_FILE_RE.test(rel)) return text;
  const at = text.indexOf(SP_LEX_OPEN), end = at < 0 ? -1 : text.indexOf('\n;\n', at);
  if (at < 0 || end < 0) return text;
  let j;
  const b64 = [...text.slice(at + SP_LEX_OPEN.length, end).matchAll(/'([A-Za-z0-9+/=]*)'/g)].map((m) => m[1]).join('');
  try { j = JSON.parse(zlib.brotliDecompressSync(Buffer.from(b64, 'base64')).toString('utf8')); } catch { return text; }
  const out = [SP_LEX_MARK];
  for (const [k, v] of Object.entries(j)) {
    if (typeof v === 'string') { out.push(`//@words ${k}`); out.push(...v.split(' ')); }
    else { out.push(`//@json ${k}`); out.push(JSON.stringify(v)); }
  }
  out.push('//@end');
  return text.slice(0, at + SP_LEX_OPEN.length) + out.join('\n') + text.slice(end);
}
/** The file again from its unpacked text: the word list packed as the plugin's builder packs it. */
function spPackText(rel, text) {
  if (!SP_LEX_FILE_RE.test(rel)) return text;
  const at = text.indexOf(SP_LEX_OPEN + SP_LEX_MARK + '\n');
  if (at < 0) return text;
  const start = at + SP_LEX_OPEN.length, end = text.indexOf('\n//@end', start);
  const lines = text.slice(start + SP_LEX_MARK.length + 1, end).split('\n');
  const j = {};
  for (let i = 0; i < lines.length;) {
    const m = /^\/\/@(words|json) (.+)$/.exec(lines[i]);
    if (!m) { i++; continue; }
    let k = i + 1; while (k < lines.length && !/^\/\/@(words|json) /.test(lines[k])) k++;
    j[m[2]] = m[1] === 'json' ? JSON.parse(lines[i + 1]) : lines.slice(i + 1, k).join(' ');
    i = k;
  }
  const packed = zlib.brotliCompressSync(Buffer.from(JSON.stringify(j), 'utf8'), { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 11 } }).toString('base64');
  const wrapped = packed.replace(/(.{1,120})/g, "  + '$1'\n").trim();
  return text.slice(0, start) + wrapped + text.slice(end + '\n//@end'.length);
}

/** The source a setup file carries: { map: { rel: Buffer }, build } - or null when the text holds none. */
function spEmbeddedOf(setupText) {
  const m = /const EMBEDDED_SRC_GZ_B64 = '([A-Za-z0-9+/=]+)';/.exec(String(setupText || ''));
  if (!m) return null;
  const raw = JSON.parse(zlib.gunzipSync(Buffer.from(m[1], 'base64')).toString('utf8'));
  const map = {};
  for (const [rel, b64] of Object.entries(raw)) map[rel] = Buffer.from(b64, 'base64');
  const build = parseInt(String(map['scripts/build-number.txt'] || '').trim(), 10);
  return { map, build: Number.isFinite(build) ? build : null };
}

// ── the folder's record and its hash ─────────────────────────────────────────────────────────────────────────────

/** The record a project folder keeps of itself: { files: { rel: hash }, chunk, at } - or null when it has none. */
const SS_RECORD = '.cb-sync.json';
/** 'none', 'damaged' or 'ok': a record that is there but cannot be read is not "not started" - starting again on it
 * would lose what the folder holds. */
function ssRecordState(dir) {
  const f = path.join(dir, SS_RECORD);
  if (!existsSync(f)) return 'none';
  return ssReadRecord(dir) ? 'ok' : 'damaged';
}
function ssReadRecord(dir) {
  try { const j = JSON.parse(readFileSync(path.join(dir, SS_RECORD), 'utf8')); return j && j.files && typeof j.files === 'object' ? j : null; } catch { return null; }
}
// (whole or not at all: written beside it and renamed over it - a record cut short by a crash left the folder stuck)
function ssWriteRecord(dir, rec) {
  const f = path.join(dir, SS_RECORD), tmp = f + '.tmp';
  writeFileSync(tmp, JSON.stringify({ ...rec, at: new Date().toISOString() }, null, 1) + '\n', 'utf8');
  for (let i = 0; ; i++) {
    try { renameSync(tmp, f); return; }
    catch (e) { if (i >= 20) throw e; const until = Date.now() + 50 * (i + 1); while (Date.now() < until) { /* (Windows: a reader holds it a moment) */ } }
  }
}
const ssIsFile = (abs) => { try { return statSync(abs).isFile(); } catch { return false; } };
/** One hash for a whole folder: every file's path and hash, in order. */
function ssTreeHash(files) {
  const h = createHash('sha256');
  for (const p of Object.keys(files).sort()) h.update(`${p}\t${files[p]}\n`);
  return h.digest('hex').slice(0, 24);
}
/** The folder as it is now, for the files its record names: { files: { rel: hash }, missing: [rel], changed: [rel] }. */
function ssScan(dir, rec) {
  const files = {}, missing = [], changed = [];
  for (const [p, want] of Object.entries(rec.files)) {
    const abs = path.join(dir, ...p.split('/'));
    if (!ssIsFile(abs)) { missing.push(p); continue; }
    files[p] = spHash(p, readFileSync(abs));
    if (files[p] !== want) changed.push(p);
  }
  return { files, missing, changed };
}
/** A project folder started from a setup file's own source (the first time). Returns the record. */
function ssStartFromSetup(dir, setupPath) {
  const emb = spEmbeddedOf(readFileSync(setupPath, 'utf8'));
  if (!emb) throw new Error(`${setupPath} carries no source - is it code-boss-setup.mjs?`);
  const files = {};
  for (const [rel, buf] of Object.entries(emb.map)) {
    const abs = path.join(dir, ...rel.split('/'));
    // (which file, and why: a start that stopped on one said only the system's words, and the folder was left half-made)
    try { mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, buf); }
    catch (e) { throw new Error(`could not write ${rel} (${e && e.code ? e.code + ': ' : ''}${String((e && e.message) || e).slice(0, 160)}) - nothing is started; ${Object.keys(files).length} of ${Object.keys(emb.map).length} files were written`); }
    files[rel] = spHash(rel, buf);
  }
  const rec = { files, chunk: 0, from: `setup file build ${emb.build}` };
  ssWriteRecord(dir, rec);
  return rec;
}

// ── a chunk: plain text ──────────────────────────────────────────────────────────────────────────────────────────
// A chunk is the changes that take a folder from one hash to the next. Plain text, read as it stands:
//   code_boss chunk 1                       the format
//   number 3 / made <when> / before <hash> / after <hash> / files <n> / left <files still to come> / check <hash of
//   everything below the head>
//   === change <path>   base <hash>  new <hash>   then "@@ <line> -<n> +<m>" and the lines, "-" as they were, "+" as they are
//   === add <path>      new <hash>   then the file, every line "+"
//   === remove <path>   base <hash>
//   === binary <path>   base <hash or ->  new <hash>   then the file in base64, every line ":"
//   === end
// Every content line starts with -, + or :, so a "=== " or "@@ " in a file is never read as a section.

const SS_HEAD = 'code_boss chunk 1';
const ssCheckOf = (body) => createHash('sha256').update(body).digest('hex').slice(0, 16);

/** The chunk as text. `chunk`: { number, before, after, files: [{ p, op, base, sha, h (change), lines (add), b64 (binary) }] }. */
function ssChunkText(chunk) {
  const out = [];
  // (a replace - make-chunk's, for a file whose diff is bigger than it - goes as its remove and its add: the folder takes
  // out the file it was made from, its base checked, and writes the new one)
  const secs = chunk.files.flatMap((f) => (f.op === 'replace' ? [{ p: f.p, op: 'remove', base: f.base }, { p: f.p, op: 'add', sha: f.sha, lines: f.lines }] : [f]));
  for (const f of secs) {
    if (f.op === 'change') {
      out.push(`=== change ${f.p}`, `base ${f.base}`, `new ${f.sha}`);
      for (const [at, del, add, was] of f.h) { out.push(`@@ ${at + 1} -${del} +${add.length}`); for (const l of was) out.push('-' + l); for (const l of add) out.push('+' + l); }
    } else if (f.op === 'add') { out.push(`=== add ${f.p}`, `new ${f.sha}`); for (const l of f.lines) out.push('+' + l); }
    else if (f.op === 'remove') out.push(`=== remove ${f.p}`, `base ${f.base}`);
    else if (f.op === 'binary') { out.push(`=== binary ${f.p}`, `base ${f.base || '-'}`, `new ${f.sha}`); for (const l of f.b64.match(/.{1,100}/g) || []) out.push(':' + l); }
  }
  out.push('=== end');
  const body = out.join('\n');
  return [SS_HEAD, `number ${chunk.number}`, `made ${chunk.made || new Date().toISOString()}`, `before ${chunk.before}`, `after ${chunk.after}`, `files ${secs.length}`, ...(chunk.left != null ? [`left ${chunk.left}`] : []), `check ${ssCheckOf(body)}`, '', body, ''].join('\n');
}

/** A chunk read back from its text (pasted, so CRLF and a cut-off end are expected): { chunk } or { problem }. */
function ssChunkFrom(text) {
  const s = String(text || '').replace(/\r\n/g, '\n');
  const at = s.indexOf(SS_HEAD + '\n');
  if (at < 0) return { problem: 'this is not a code_boss chunk' };
  const lines = s.slice(at).split('\n');
  const head = {};
  let i = 1;
  for (; i < lines.length && lines[i] !== ''; i++) { const m = /^(\w+) (.*)$/.exec(lines[i]); if (m) head[m[1]] = m[2].trim(); }
  const end = lines.indexOf('=== end', i);
  if (end < 0) return { problem: 'the chunk is cut off - its end is missing (was all of it pasted?)' };
  const bodyLines = lines.slice(i + 1, end + 1);
  if (ssCheckOf(bodyLines.join('\n')) !== head.check) return { problem: 'the chunk is damaged - its check does not match (was all of it pasted, unchanged?)' };
  const files = [];
  let cur = null, hunk = null;
  for (const l of bodyLines) {
    const sec = /^=== (change|add|remove|binary) (.+)$/.exec(l);
    // (a path is relative, forward slashes, inside the folder - "../x", "C:/x", "/x" or a backslash is refused, never written)
    if (sec && (/^[\/]|^[A-Za-z]:|\\|(^|\/)\.\.?(\/|$)|\/\/|[\0<>|?*"]/.test(sec[2]) || !sec[2].trim())) return { problem: `the chunk names a path that is not inside the folder: "${sec[2].slice(0, 80)}" - it is not applied` };
    if (sec) { cur = { op: sec[1], p: sec[2], h: [], lines: [], b64: '' }; files.push(cur); hunk = null; continue; }
    if (l === '=== end') break;
    if (!cur) return { problem: `the chunk is damaged - "${l.slice(0, 60)}" comes before any file` };
    let m;
    if ((m = /^base (\S+)$/.exec(l))) { cur.base = m[1] === '-' ? null : m[1]; continue; }
    if ((m = /^new (\S+)$/.exec(l))) { cur.sha = m[1]; continue; }
    if ((m = /^@@ (\d+) -(\d+) \+(\d+)$/.exec(l))) { hunk = [Number(m[1]) - 1, Number(m[2]), [], []]; cur.h.push(hunk); continue; }
    if (l.startsWith(':') && cur.op === 'binary') { cur.b64 += l.slice(1); continue; }
    if (l.startsWith('+')) { if (cur.op === 'add') cur.lines.push(l.slice(1)); else if (hunk) hunk[2].push(l.slice(1)); else return { problem: `the chunk is damaged in ${cur.p}` }; continue; }
    if (l.startsWith('-') && hunk) { hunk[3].push(l.slice(1)); continue; }
    return { problem: `the chunk is damaged in ${cur.p}: "${l.slice(0, 60)}"` };
  }
  const number = Number(head.number);
  if (!Number.isFinite(number) || !head.before || !head.after) return { problem: 'the chunk is damaged - its head is incomplete' };
  if (files.length !== Number(head.files)) return { problem: `the chunk is damaged - it says ${head.files} files and holds ${files.length}` };
  return { chunk: { number, made: head.made, before: head.before, after: head.after, files, ...(head.left != null ? { left: Number(head.left) } : {}) } };
}

/**
 * What a chunk would make of a folder: { files: { rel: Buffer|null }, record } or { problems }. Nothing is written.
 * The folder must be exactly what the chunk was made from - its hash, and each file the chunk touches.
 */
function ssPlan(dir, chunk) {
  const rec = ssReadRecord(dir);
  if (!rec) return { problems: [ssRecordState(dir) === 'damaged' ? `the folder's record (${SS_RECORD}) is damaged, so what is in the folder cannot be told - start a new project folder from your setup file, in an empty folder, and apply the chunks to it from the first` : `${dir} is not a project folder yet - start it from your setup file first`] };
  const scan = ssScan(dir, rec);
  const problems = [];
  // AN APPLY THAT WAS CUT OFF (the machine went down while it wrote): the record is written last, so it is still the chunk's
  // "before", and some of the chunk's files are already as it leaves them. The same chunk pasted again finishes it: a
  // file it touches may be as it was or as the chunk leaves it; anything else changed is still refused.
  const touched = new Map(chunk.files.map((f) => [f.p, f]));
  const doneAlready = (p) => { const f = touched.get(p); if (!f) return false; if (f.op === 'remove') return !existsSync(path.join(dir, ...p.split('/'))); return scan.files[p] === f.sha; };
  const missing = scan.missing.filter((p) => !doneAlready(p)), changed = scan.changed.filter((p) => !doneAlready(p));
  if (missing.length) problems.push(`missing from the folder: ${missing.slice(0, 8).join(', ')}${missing.length > 8 ? ` and ${missing.length - 8} more` : ''}`);
  if (changed.length) problems.push(`changed in the folder since the last chunk: ${changed.slice(0, 8).join(', ')}${changed.length > 8 ? ` and ${changed.length - 8} more` : ''}`);
  if (problems.length) return { problems };
  const now = ssTreeHash(rec.files);
  if (now === chunk.after) return { problems: [`chunk ${chunk.number} is in this folder already`] };
  if (now !== chunk.before) return { problems: [`chunk ${chunk.number} goes on a folder at ${chunk.before.slice(0, 8)}; this one is at ${now.slice(0, 8)} (after chunk ${rec.chunk || 0}) - the chunks go in order`] };
  const out = {}, files = { ...rec.files };
  // (what the chunk takes out, before anything goes in - a name that changes only its case is the same file on Windows,
  // and a folder the chunk empties may become a file)
  const removedLower = new Set(chunk.files.filter((f) => f.op === 'remove').map((f) => f.p.toLowerCase()));
  const emptiedBy = (rel) => { const pre = rel + '/'; const inside = Object.keys(rec.files).filter((p) => p.startsWith(pre)); return inside.length && inside.every((p) => removedLower.has(p.toLowerCase())); };
  for (const f of chunk.files) {
    const abs = path.join(dir, ...f.p.split('/'));
    let isDir = false; try { isDir = statSync(abs).isDirectory(); } catch {}
    if (isDir && !emptiedBy(f.p)) { problems.push(`${f.p}: a folder is where the chunk puts a file`); continue; }
    const cur = !isDir && removedLower.has(f.p.toLowerCase()) && f.op !== 'remove' ? null : ssIsFile(abs) ? readFileSync(abs) : null;
    const curHash = cur ? spHash(f.p, cur) : null;
    // (written already by an apply that was cut off: as the chunk leaves it)
    if (f.op === 'remove' && !cur && f.p in rec.files) { out[f.p] = null; delete files[f.p]; continue; }
    if (f.op !== 'remove' && cur && curHash === f.sha) { out[f.p] = cur; files[f.p] = f.sha; continue; }
    if (f.op === 'add' && cur && !(f.p in rec.files)) problems.push(`${f.p}: the chunk adds it, and a file is already there`);
    if (f.op !== 'add' && f.base !== undefined && f.base !== null && curHash !== f.base) { problems.push(`${f.p}: not the file the chunk was made from`); continue; }
    if (f.op === 'remove') { out[f.p] = null; delete files[f.p]; continue; }
    let buf;
    if (f.op === 'add') buf = Buffer.from(spPackText(f.p, f.lines.join('\n')), 'utf8');
    else if (f.op === 'binary') buf = Buffer.from(f.b64, 'base64');
    else {
      const was = cur.toString('utf8'), crlf = /\r\n/.test(was);
      const src = spTextOf(f.p, cur).split('\n'), lines = [];
      let pos = 0;
      for (const [at, del, add, gone] of [...f.h].sort((a, b) => a[0] - b[0])) {
        while (pos < at) lines.push(src[pos++]);
        // (the lines the chunk says it takes out are the ones that are there)
        for (let k = 0; k < del; k++) if (src[at + k] !== gone[k]) { problems.push(`${f.p}: line ${at + k + 1} is not what the chunk takes out`); break; }
        for (const l of add) lines.push(l);
        pos = at + del;
      }
      while (pos < src.length) lines.push(src[pos++]);
      let text = spPackText(f.p, lines.join('\n'));
      if (crlf) text = text.replace(/\n/g, '\r\n');
      buf = Buffer.from(text, 'utf8');
    }
    if (spHash(f.p, buf) !== f.sha) problems.push(`${f.p}: did not come out as the chunk says`);
    out[f.p] = buf; files[f.p] = f.sha;
  }
  if (!problems.length && ssTreeHash(files) !== chunk.after) problems.push(`the folder would not come out at ${chunk.after.slice(0, 8)}`);
  return problems.length ? { problems } : { files: out, record: { ...rec, files, chunk: chunk.number, ...(chunk.left != null ? { left: chunk.left } : {}) } };
}

/** Apply a chunk: checked whole first (ssPlan), then written. { ok, record, written } or { ok: false, problems }. */
function ssApply(dir, chunk) {
  const plan = ssPlan(dir, chunk);
  if (plan.problems) return { ok: false, problems: plan.problems };
  let written = 0;
  const entries = Object.entries(plan.files);
  // (removals first: on Windows "Foo.mjs" out and "foo.mjs" in is one file, and a folder emptied may become a file; the
  // folders a removal leaves empty go too, up to the project folder)
  for (const [p, buf] of entries) {
    if (buf !== null) continue;
    const abs = path.join(dir, ...p.split('/'));
    try { rmSync(abs, { force: true }); } catch {}
    for (let d = path.dirname(abs); path.relative(dir, d) && !path.relative(dir, d).startsWith('..'); d = path.dirname(d)) { try { if (readdirSync(d).length) break; rmdirSync(d); } catch { break; } }
  }
  for (const [p, buf] of entries) {
    if (buf === null) continue;
    const abs = path.join(dir, ...p.split('/'));
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, buf); written++;
  }
  ssWriteRecord(dir, plan.record);
  return { ok: true, record: plan.record, written };
}

/**
 * THE WHOLE PROJECT INTO THE RELEASE'S FOLDER (a Heads up, 2026-11-02: a release pushes only what the setup file
 * carries, so the tests and docs in the folder never reached GitLab; the developer: "let's push everything except
 * the setup script"). Every file of the project folder is copied into `target` (the release's code_boss-src), which
 * the release then commits and pushes whole; one the project no longer has, copied by an earlier release, is taken
 * out. What was copied is kept in `listFile`, outside the folder: the release's extract reads it too (CB_PROJECT_FILES),
 * so its prune leaves these files alone. { copied, removed }.
 */
function ssCopyTo(dir, target, listFile) {
  const rec = ssReadRecord(dir);
  if (!rec) throw new Error('the project folder has no record - start it first');
  let lists = {};
  try { lists = JSON.parse(readFileSync(listFile, 'utf8')) || {}; } catch { lists = {}; }
  const key = path.resolve(target).toLowerCase();
  const before = Array.isArray(lists[key]) ? lists[key] : [];
  let copied = 0, removed = 0;
  for (const p of Object.keys(rec.files)) {
    const abs = path.join(target, ...p.split('/'));
    mkdirSync(path.dirname(abs), { recursive: true });
    copyFileSync(path.join(dir, ...p.split('/')), abs); copied++;
  }
  for (const p of before) if (!(p in rec.files)) { try { rmSync(path.join(target, ...p.split('/')), { force: true }); removed++; } catch {} }
  lists[key] = Object.keys(rec.files);
  mkdirSync(path.dirname(listFile), { recursive: true });
  writeFileSync(listFile, JSON.stringify(lists), 'utf8');
  return { copied, removed };
}

/**
 * The project folder built where it cannot be touched: its files copied to `buildDir`, the build number set one back
 * so build.mjs makes this build's number, and built (node scripts/build.mjs). { ok, dir, build } or { ok: false, problem }.
 */
function ssBuild(dir, buildDir, log = (m) => console.log(m)) {
  const rec = ssReadRecord(dir);
  if (!rec) return { ok: false, problem: 'the project folder has no record - start it first' };
  try { rmSync(buildDir, { recursive: true, force: true }); } catch {}
  for (const p of Object.keys(rec.files)) {
    const abs = path.join(buildDir, ...p.split('/'));
    mkdirSync(path.dirname(abs), { recursive: true });
    copyFileSync(path.join(dir, ...p.split('/')), abs);
  }
  const nf = path.join(buildDir, 'scripts', 'build-number.txt');
  const build = parseInt(readFileSync(nf, 'utf8'), 10);
  writeFileSync(nf, `${build - 1}\n`);
  log(`building build ${build} in ${buildDir} ...`);
  const r = spawnSync(process.execPath, ['scripts/build.mjs'], { cwd: buildDir, encoding: 'utf8', maxBuffer: 64 * 1048576 });
  if (r.status !== 0 || !existsSync(path.join(buildDir, 'dist', 'code-boss-setup.mjs'))) return { ok: false, problem: `the build failed (exit ${r.status}): ${String(r.stderr || r.stdout || '').trim().split('\n').slice(-8).join(' / ')}` };
  return { ok: true, dir: buildDir, build };
}

// ====== src/release-settings.mjs ======
// ── A RELEASE'S SETTINGS: what the release command's switches gave, kept ─────────────────────────────────────────
// ~/.code_boss/build-config.json (the repository, the source folder, the plugins folder and which plugins ship) and
// gitlab-creds.json (user, token - the token never goes back to a page). Read and saved here for both windows: the
// release window (release-ui.mjs) and the setup window (setup-update-ui.mjs; the developer, 2026-11-03: "I expected in
// the setup ui to have the options I was setting in the flags before I release").

const rsHome = () => path.join(process.env.CB_HOME || homedir(), '.code_boss');
const rsCfgPath = () => path.join(rsHome(), 'build-config.json');
const rsCredsPath = () => path.join(rsHome(), 'gitlab-creds.json');
const rsReadJson = (f) => { try { const j = JSON.parse(readFileSync(f, 'utf8')); return j && typeof j === 'object' ? j : {}; } catch { return {}; } };
const rsWriteJson = (f, v) => { mkdirSync(path.dirname(f), { recursive: true }); writeFileSync(f, JSON.stringify(v, null, 2) + '\n', 'utf8'); };

// ── the team's plugins: picked from the admin's own plugin folder, shipped with the release ──────────────────
// (the developer, 2026-10-30: plugins built "inside my own local container in prod" go out with code_boss; which ones,
// and which are on by default, chosen in the release window.) The app installs them by src/plugins/team.mjs's rules.

// where the admin's plugins are: what the window saved; else the container's home on the production box; else this
// account's own
function setupPluginsDir(cfg = {}) {
  if (cfg && String(cfg.pluginsDir || '').trim()) return String(cfg.pluginsDir).trim();
  const container = 'z:/home/.code_boss/plugins';
  if (process.platform === 'win32' && existsSync(container)) return container;
  return path.join(rsHome(), 'plugins');
}

const SETUP_PLUGIN_RE = /^([a-z0-9][a-z0-9._-]*?)__([^_][^\\/]*)\.mjs$/i;
const setupVersionCmp = (a, b) => String(a).localeCompare(String(b), undefined, { numeric: true });
const setupSha = (s) => createHash('sha256').update(s).digest('hex');

/** The admin's plugins, the newest version of each: [{ name, file, version, sha, size, description }]. */
function setupLocalPlugins(dir) {
  let files = [];
  try { files = readdirSync(dir); } catch { return []; }
  const best = new Map();
  for (const f of files) {
    const m = SETUP_PLUGIN_RE.exec(f);
    if (!m || f.startsWith('.')) continue;
    const name = m[1].toLowerCase(), have = best.get(name);
    if (!have || setupVersionCmp(m[2], have.version) > 0) best.set(name, { name, file: f, version: m[2] });
  }
  const out = [];
  for (const p of best.values()) {
    try {
      const src = readFileSync(path.join(dir, p.file));
      const d = /description\s*:\s*(['"`])((?:(?!\1)[^\\\n]|\\.){0,240})\1/.exec(src.toString('utf8'));
      out.push({ ...p, sha: setupSha(src), size: src.length, description: d ? d[2] : '' });
    } catch { /* unreadable: not offered */ }
  }
  return out.sort((a, b) => a.name.localeCompare(b.name));
}

/** The plugin folder as a page shows it: each plugin with what it is set to and whether it changed since the last release. */
function relPluginView(cfg) {
  const dir = setupPluginsDir(cfg);
  const ship = new Map((Array.isArray(cfg.shipPlugins) ? cfg.shipPlugins : []).map((p) => [String(p.name).toLowerCase(), p]));
  const last = (cfg.lastShipped && cfg.lastShipped.plugins) || {};
  const local = setupLocalPlugins(dir);
  const rows = local.map((p) => {
    const s = ship.get(p.name), was = last[p.name];
    const status = !was ? 'not shipped yet' : was.sha === p.sha ? 'as shipped' : `changed since ${was.file === p.file ? 'shipped' : was.file + ' shipped'}`;
    return { name: p.name, file: p.file, version: p.version, size: p.size, description: p.description, ship: !!s, enabled: s ? s.enabled !== false : true, status, changed: !was || was.sha !== p.sha };
  });
  // chosen, but gone from the folder: said, so it is not shipped silently short
  for (const [name] of ship) if (!local.some((p) => p.name === name)) rows.push({ name, file: '', version: '', size: 0, description: '', ship: true, enabled: ship.get(name).enabled !== false, status: 'missing from the folder', missing: true });
  return { dir, exists: existsSync(dir), rows };
}

// Accept a GitLab repo URL in whatever shape a user pastes and return the clean
// web URL: no embedded auth, no trailing slash, no pasted browser tail
// (…/-/tree/main), and WITH-OR-WITHOUT a trailing .git both fine (downstream the
// push remote re-adds .git and the API path strips it — so the stored form just
// needs to be the canonical web URL). scp-style (git@host:group/repo) is
// converted to https. Non-http sources (a local bare repo in tests) pass through
// untouched. Returns '' for empty input.
function normalizeRepoUrl(raw) {
  let s = String(raw == null ? '' : raw).trim().replace(/^['"]+|['"]+$/g, '').trim();
  if (!s) return '';
  const scp = /^[\w.+-]+@([\w.-]+):(.+)$/.exec(s);          // git@host:group/repo[.git]
  if (scp && !/^[a-z][\w+.-]*:\/\//i.test(s)) s = 'https://' + scp[1] + '/' + scp[2];
  if (/^https?:\/\//i.test(s)) {
    try {
      const u = new URL(s);
      u.username = ''; u.password = ''; u.hash = ''; u.search = '';
      u.pathname = u.pathname.replace(/\/-\/.*$/, '').replace(/\/+$/, '').replace(/\.git$/i, '').replace(/\/+$/, '');
      s = u.origin + u.pathname;
    } catch { /* unparseable — return the trimmed input so the caller errors clearly */ }
  }
  return s;
}

/** The settings as a page shows them (never the token, only whether one is saved). */
function relSettingsView() {
  const cfg = rsReadJson(rsCfgPath()), creds = rsReadJson(rsCredsPath());
  return {
    updateSource: cfg.updateSource || '', releaseDir: cfg.releaseDir || '', pluginsDir: cfg.pluginsDir || '',
    glUser: creds.user || '', hasToken: !!creds.token, plugins: relPluginView(cfg),
    lastShipped: cfg.lastShipped ? { build: cfg.lastShipped.build, channel: cfg.lastShipped.channel, at: cfg.lastShipped.at } : null,
  };
}

/** A page's Save: what it sent, kept. An empty token field keeps the saved token. */
function relSaveSettings(b = {}) {
  const cfg = rsReadJson(rsCfgPath()), creds = rsReadJson(rsCredsPath());
  if (typeof b.updateSource === 'string') cfg.updateSource = normalizeRepoUrl(b.updateSource);
  if (typeof b.releaseDir === 'string' && b.releaseDir.trim()) cfg.releaseDir = path.resolve(b.releaseDir.trim());
  if (typeof b.pluginsDir === 'string') { if (b.pluginsDir.trim()) cfg.pluginsDir = b.pluginsDir.trim(); else delete cfg.pluginsDir; }
  if (Array.isArray(b.ship)) cfg.shipPlugins = b.ship.filter((p) => p && p.name).map((p) => ({ name: String(p.name).toLowerCase(), enabled: p.enabled !== false }));
  rsWriteJson(rsCfgPath(), cfg);
  if (typeof b.glUser === 'string' || (typeof b.glToken === 'string' && b.glToken.trim())) {
    if (typeof b.glUser === 'string') creds.user = b.glUser.trim();
    if (typeof b.glToken === 'string' && b.glToken.trim()) creds.token = b.glToken.trim();
    rsWriteJson(rsCredsPath(), creds);
  }
}

/** Why a release cannot start with the saved settings, or '' when it can. */
function relReleaseProblem({ push = true } = {}) {
  const cfg = rsReadJson(rsCfgPath()), creds = rsReadJson(rsCredsPath());
  if (!cfg.updateSource) return 'The repository is needed first.';
  if (push && !(creds.user && creds.token)) return 'A GitLab user and token are needed to push.';
  return '';
}

// ====== src/release-channels.mjs ======
// ── DISTRIBUTION: WHAT USERS DOWNLOAD, AND WHICH BUILD EACH CHANNEL IS ON ────────────────────────────────────────────
// (the developer, 2026-11-03: "the crux is, we're using the repo both for source control and distribution"; a review
// the same day: every release pushed main with --force from the machine's own folder, so with several maintainers each
// release replaced the others' history.) One GitLab repository, two jobs kept apart:
//   SOURCE: ordinary branches (main is the truth). No tool here ever pushes one with force.
//   DISTRIBUTION: branches only the release writes, holding no source -
//     dist     releases/ (manifest.json, the bundle, the docx jars, notes.json): one commit per release, each on top
//              of GitLab's, never forced; "Release build N" with "From: <branch> <commit>" (the source it was made from)
//     sandbox  the container image (sandbox-image-cli.mjs), as before
//   and tags:
//     build-N, sandbox-build-N               fixed: build N's dist commit, and its image. Created once, never moved -
//                                            pushing one that is there already fails, so two releases cannot both be N
//     devtest beta production, sandbox-<c>   the channels: the only tags that move
// Everyone's code_boss follows its channel's tag (check-update reads releases/manifest.json there) and takes whatever
// build is there when it is not the one it runs - an older one too: promoting a build, or putting an old one back, is
// moving a channel's tags onto build-N and sandbox-build-N. Nothing is built.
// The list is GitLab's tags (ls-remote: nothing downloaded), so every maintainer sees every release.

const REL_CHANNELS = ['devtest', 'beta', 'production'];
const REL_DIST_BRANCH = 'dist';

const rcGit = (dir, args) => spawnSync('git', args, { cwd: dir, encoding: 'utf8', windowsHide: true, maxBuffer: 256 * 1048576 });
// (never an authed URL in what is said)
const rcHide = (s) => String(s || '').replace(/\/\/[^@/\s]+@/g, '//***@');
const rcSaid = (r) => rcHide(`${r.stderr || ''}${r.stdout || ''}`).trim();

/** The remote a push goes to: the repository with the login in it, for that one push only - the stored remote (and
 * .git/config) never has the token. A folder, ssh or other non-http source as it is. */
function setupAuthedRemote(updateSource, creds) {
  if (!/^https?:/i.test(updateSource)) return updateSource;
  const u = new URL(updateSource);
  u.username = creds.user;
  u.password = creds.token;
  if (!u.pathname.endsWith('.git')) u.pathname = u.pathname.replace(/\/+$/, '') + '.git';
  return u.href;
}

/** GitLab's tags, without downloading anything: { ok, tags: { name: sha } } or { ok: false, problem }. */
function relRemoteTags({ updateSource, creds = {}, cwd = process.cwd() }) {
  if (!updateSource) return { ok: false, problem: 'The repository is not set.' };
  const r = rcGit(cwd, ['ls-remote', '--tags', setupAuthedRemote(updateSource, creds)]);
  if (r.status !== 0) return { ok: false, problem: 'GitLab could not be asked for its tags: ' + rcSaid(r).slice(0, 300) };
  const tags = {};
  for (const l of String(r.stdout || '').split(/\r?\n/)) {
    const m = /^([0-9a-f]{40})\trefs\/tags\/([^\s^]+)$/.exec(l.trim());
    if (m) tags[m[2]] = m[1];
  }
  return { ok: true, tags };
}

/**
 * Every release on GitLab, newest first: [{ build, sha, channels: [...], image: { sha, channels } | null }]; where each
 * channel is (channels / imageChannels: { channel: sha }); a channel on no build-N (elsewhere / imageElsewhere).
 * `tags` instead of asking GitLab (tests, or a list just read).
 */
function relChannelList({ updateSource, creds = {}, tags = null } = {}) {
  const t = tags ? { ok: true, tags } : relRemoteTags({ updateSource, creds });
  if (!t.ok) return t;
  const T = t.tags, channels = {}, imageChannels = {};
  for (const c of REL_CHANNELS) { if (T[c]) channels[c] = T[c]; if (T['sandbox-' + c]) imageChannels[c] = T['sandbox-' + c]; }
  const builds = Object.keys(T).map((n) => /^build-(\d+)$/.exec(n)).filter(Boolean).map((m) => {
    const sha = T[m[0]], isha = T['sandbox-build-' + m[1]];
    return {
      build: m[1], sha, channels: REL_CHANNELS.filter((c) => channels[c] === sha),
      image: isha ? { sha: isha, channels: REL_CHANNELS.filter((c) => imageChannels[c] === isha) } : null,
    };
  }).sort((a, b) => Number(b.build) - Number(a.build));
  const elsewhere = REL_CHANNELS.filter((c) => channels[c] && !builds.some((b) => b.sha === channels[c]));
  const imageElsewhere = REL_CHANNELS.filter((c) => imageChannels[c] && !builds.some((b) => b.image && b.image.sha === imageChannels[c]));
  return { ok: true, builds, channels, imageChannels, elsewhere, imageElsewhere, tags: T };
}

/** The highest build on GitLab (0 when there is none yet). */
const relHighestBuild = (tags) => Math.max(0, ...Object.keys(tags || {}).map((n) => (/^build-(\d+)$/.exec(n) || [])[1]).filter(Boolean).map(Number));

/**
 * THE RELEASES MADE BEFORE dist: "Release build N" commits on main in an old release folder. Each one without a build-N
 * on GitLab gets it (created, never forced), so they stay in the list and can be gone back to. Returns how many.
 */
function relTagLegacy({ dir, updateSource, creds = {}, tags = {}, log = () => {} }) {
  if (!dir || !existsSync(path.join(dir, '.git'))) return 0;
  const l = rcGit(dir, ['log', 'main', '--format=%H%x09%s']);
  if (l.status !== 0) return 0;
  const refs = [];
  for (const line of String(l.stdout || '').split(/\r?\n/)) {
    const m = /^([0-9a-f]{40})\tRelease build (\d+)\s*$/.exec(line.trim());
    if (m && !tags['build-' + m[2]] && !refs.some((r) => r.endsWith(':refs/tags/build-' + m[2]))) refs.push(`${m[1]}:refs/tags/build-${m[2]}`);
  }
  if (!refs.length) return 0;
  const p = rcGit(dir, ['push', setupAuthedRemote(updateSource, creds), ...refs]);
  if (p.status !== 0) { log(`the releases made before could not be tagged (they stay out of the list): ${rcSaid(p).slice(-300)}`); return 0; }
  log(`the ${refs.length} release(s) made before, from ${dir}, are on GitLab as build-N tags now`);
  return refs.length;
}

/**
 * The dist folder on GitLab's dist branch (or a new one, before the first release). Before a build: the release's
 * notes.json history is in it. { ok } or { ok: false, problem }.
 */
function relDistFetch({ distDir, updateSource, creds = {}, push = true }) {
  mkdirSync(distDir, { recursive: true });
  if (!existsSync(path.join(distDir, '.git'))) rcGit(distDir, ['init', '-q']);
  if (!(rcGit(distDir, ['config', 'user.email']).stdout || '').trim()) {
    rcGit(distDir, ['config', 'user.name', creds.user || 'code-boss']);
    rcGit(distDir, ['config', 'user.email', `${creds.user || 'code-boss'}@code-boss.local`]);
  }
  let onRemote = false;
  if (push) {
    const f = rcGit(distDir, ['fetch', '-q', '--no-tags', setupAuthedRemote(updateSource, creds), `+refs/heads/${REL_DIST_BRANCH}:refs/remotes/release/${REL_DIST_BRANCH}`]);
    if (f.status === 0) onRemote = true;
    else if (!/couldn't find remote ref|could not find remote ref/i.test(rcSaid(f))) return { ok: false, problem: `GitLab's ${REL_DIST_BRANCH} branch could not be fetched: ${rcSaid(f).slice(0, 300)}` };
  }
  const r = onRemote ? rcGit(distDir, ['checkout', '-q', '-f', '-B', REL_DIST_BRANCH, `refs/remotes/release/${REL_DIST_BRANCH}`])
    : rcGit(distDir, ['rev-parse', '--verify', '-q', `refs/heads/${REL_DIST_BRANCH}`]).status === 0 ? rcGit(distDir, ['checkout', '-q', '-f', REL_DIST_BRANCH])
    : rcGit(distDir, ['checkout', '-q', '--orphan', REL_DIST_BRANCH]);
  if (r.status !== 0) return { ok: false, problem: `the dist folder could not be put on ${REL_DIST_BRANCH}: ${rcSaid(r).slice(0, 300)}` };
  return { ok: true, onRemote };
}

/** What users download of a build: the files its releases/manifest.json names, and the notes history. */
function relDistFiles(root) {
  const m = JSON.parse(readFileSync(path.join(root, 'releases', 'manifest.json'), 'utf8'));
  const out = ['releases/manifest.json', m.file, ...(m.helperJar ? [m.helperJar] : []), ...(Array.isArray(m.jars) ? m.jars : [])];
  if (existsSync(path.join(root, 'releases', 'notes.json'))) out.push('releases/notes.json');
  return [...new Set(out.filter(Boolean))];
}

/**
 * Build N's releases/ (what users download) committed on dist, on top of what relDistFetch put there; build-N made, the
 * channel's tag moved; pushed together (--atomic), dist not forced. Exit code; what it does is said through `log`.
 */
function relPublishDist({ distDir, root, files, build, channel, from = '', updateSource, creds = {}, push = true, log = (m) => console.log(m) }) {
  for (const e of readdirSync(distDir)) if (e !== '.git') rmSync(path.join(distDir, e), { recursive: true, force: true });
  for (const f of files) { mkdirSync(path.dirname(path.join(distDir, f)), { recursive: true }); copyFileSync(path.join(root, f), path.join(distDir, f)); }
  rcGit(distDir, ['add', '-A']);
  const c = rcGit(distDir, ['commit', '-q', '--allow-empty', '-m', `Release build ${build}`, ...(from ? ['-m', `From: ${from}`] : [])]);
  if (c.status !== 0) { log('the dist commit failed: ' + rcSaid(c).slice(0, 300)); return 1; }
  rcGit(distDir, ['tag', '-f', `build-${build}`]);
  rcGit(distDir, ['tag', '-f', channel]);
  if (!push) { log(`build ${build} is committed in ${distDir} (dist) and tagged ${channel} there - not pushed.`); return 0; }
  const p = rcGit(distDir, ['push', '--atomic', setupAuthedRemote(updateSource, creds), REL_DIST_BRANCH, `refs/tags/build-${build}`, `+refs/tags/${channel}`]);
  if (p.status !== 0) {
    const said = rcSaid(p);
    if (/already exists|non-fast-forward|fetch first|rejected/i.test(said)) log(`Another release reached GitLab first (its dist moved, or build ${build} is there already). Nothing was pushed: release again - it goes on top, with the next number.`);
    else log(`the push failed: ${said.slice(-400)}`);
    return 1;
  }
  log(`pushed: dist, build-${build}, and ${channel} on it`);
  return 0;
}

// a commit here, fetched (only it) when this folder does not have it - a push names it by its id
function rcHave(dir, sha, updateSource, creds, tag, log) {
  if (rcGit(dir, ['cat-file', '-e', `${sha}^{commit}`]).status === 0) return true;
  log(`fetching ${tag} (only that commit) ...`);
  const f = rcGit(dir, ['fetch', '-q', '--no-tags', '--depth=1', setupAuthedRemote(updateSource, creds), `refs/tags/${tag}`]);
  return f.status === 0 && rcGit(dir, ['cat-file', '-e', `${sha}^{commit}`]).status === 0;
}

/**
 * Move a channel to build N: code_boss's tag onto build-N and, when there is one, the container's onto sandbox-build-N.
 * Each push is --force-with-lease on where the list saw the tag, so a move made elsewhere in between is not undone
 * (refused, and said). When the image's push fails, code_boss's is put back: a channel never means two builds.
 * `dir` is a folder to push from (a bare one is made when it is not there). Exit code.
 */
function relMoveChannel({ dir, channel, build, updateSource, creds = {}, log = (m) => console.log(m) }) {
  if (!REL_CHANNELS.includes(channel)) { log(`Nothing moved: there is no channel "${channel}".`); return 1; }
  const list = relChannelList({ updateSource, creds });
  if (!list.ok) { log('Nothing moved: ' + list.problem); return 1; }
  const b = list.builds.find((x) => x.build === String(build));
  if (!b) { log(`Nothing moved: there is no build ${build} on GitLab.`); return 1; }
  const was = list.builds.find((x) => x.sha === list.channels[channel]);
  if (!b.image) log(`(there is no image of build ${build}: the container's ${channel} stays where it is)`);
  log(`moving ${channel} to build ${build}${b.image ? ', code_boss and its image,' : ''}${was ? ` (it was on build ${was.build})` : ''} ...`);
  if (!existsSync(path.join(dir, '.git')) && !existsSync(path.join(dir, 'HEAD'))) { mkdirSync(dir, { recursive: true }); rcGit(dir, ['init', '-q', '--bare']); }
  const remote = setupAuthedRemote(updateSource, creds);
  const move = (tag, sha, old, fixed) => {
    if (!rcHave(dir, sha, updateSource, creds, fixed, log)) { log(`${fixed} could not be fetched`); return false; }
    const p = rcGit(dir, ['push', `--force-with-lease=refs/tags/${tag}:${old || ''}`, remote, `${sha}:refs/tags/${tag}`]);
    if (p.status === 0) return true;
    log(/stale info|rejected/i.test(rcSaid(p)) ? `${tag} was moved elsewhere since the list was read - not moved over that; look at the list again` : `the push of ${tag} failed: ${rcSaid(p).slice(-300)}`);
    return false;
  };
  if (!move(channel, b.sha, list.channels[channel], `build-${build}`)) { log('Nothing moved.'); return 1; }
  if (b.image && !move('sandbox-' + channel, b.image.sha, list.imageChannels[channel], `sandbox-build-${build}`)) {
    const back = list.channels[channel];
    const undo = rcGit(dir, ['push', `--force-with-lease=refs/tags/${channel}:${b.sha}`, remote, back ? `${back}:refs/tags/${channel}` : `:refs/tags/${channel}`]);
    log(undo.status === 0 ? `Nothing moved: the image's tag could not be pushed, so code_boss's ${channel} was put back${was ? ` on build ${was.build}` : ''}.`
      : `ONLY HALF MOVED: code_boss's ${channel} is on build ${build}, its image's is not, and putting code_boss's back failed too. Press the button again.`);
    return 1;
  }
  log(`${channel} is now build ${build}${b.image ? ', code_boss and the container both' : ''}: everyone following ${channel} gets it at their next update${was && Number(was.build) > Number(build) ? ` - an older build than the ${was.build} they have, which they take` : ''}.`);
  return 0;
}

// ====== src/setup-update-ui.mjs ======
// setup-update-ui.mjs - THE SETUP WINDOW: CHUNKS IN, COMMITTED. Opened from a desktop shortcut; a chunk is checked,
// then applied, then committed on the project's branch and pushed (the developer, 2026-11-03: "I want the setup for me
// to run only moving chunks in and committing them and we need a separate ui for building/releasing"). Releases are
// the release window's, run from the project folder (scripts/release-window.mjs) like from any checkout.
//
// dist/code-boss-setup-update.mjs (scripts/build.mjs) is this, src/setup-sync.mjs and what it uses, a few dozen KB. It
// keeps the project folder (setup-sync.mjs): started once from a setup file, then a chunk at a time. The folder is a git
// checkout of the source repository: each chunk is one commit, on top of what the branch had, never forced - when the
// branch has commits made elsewhere, the push is refused and said, and nothing of theirs is undone.
// Chrome in app mode on 127.0.0.1 with a per-run token and our own Host, as the release window.

const suHome = () => path.join(process.env.CB_HOME || process.env.USERPROFILE || process.env.HOME || '.', '.code_boss');
const suCfgPath = () => path.join(suHome(), 'setup-window.json');
// what went wrong, kept (live, 2026-11-03: a start that failed said so for a moment, then the page's refresh put "Not
// started yet" over it, and nothing was written anywhere)
const suLogPath = () => path.join(suHome(), 'setup-window.log');
const suLog = (what) => { try { mkdirSync(suHome(), { recursive: true }); appendFileSync(suLogPath(), `${new Date().toISOString()}  ${what}\n`); } catch { /* the window goes on */ } };
const suReadJson = (f) => { try { const j = JSON.parse(readFileSync(f, 'utf8')); return j && typeof j === 'object' ? j : {}; } catch { return {}; } };
const suWriteJson = (f, v) => { mkdirSync(path.dirname(f), { recursive: true }); writeFileSync(f, JSON.stringify(v, null, 2) + '\n', 'utf8'); };

function suFindChrome(env = process.env) {
  const c = [path.join(env.LOCALAPPDATA || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    path.join(env.ProgramFiles || 'C:\\Program Files', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    path.join(env['ProgramFiles(x86)'] || 'C:\\Program Files (x86)', 'Google', 'Chrome', 'Application', 'chrome.exe')];
  return c.find((p) => { try { return existsSync(p); } catch { return false; } }) || '';
}
function suOpenWindow(url) {
  const chrome = suFindChrome();
  if (!chrome) return false;
  const child = spawn(chrome, ['--app=' + url, '--user-data-dir=' + path.join(suHome(), 'data', 'chrome-setup'), '--no-first-run', '--new-window', '--window-size=940,860'], { detached: true, stdio: 'ignore' });
  child.on('error', () => {});
  child.unref();
  return true;
}
/** The Desktop's "Code Boss Setup": node running this file (a run with its own CB_HOME keeps it in <CB_HOME>\Desktop). */
function suShortcutPath() {
  const own = process.env.CB_HOME ? path.join(process.env.CB_HOME, 'Desktop') : path.join(process.env.USERPROFILE || process.env.HOME || '.', 'Desktop');
  return path.join(own, 'Code Boss Setup.lnk');
}
function suMakeShortcut(selfPath) {
  if (process.platform !== 'win32') return false;
  const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
  const own = process.env.CB_HOME ? path.join(process.env.CB_HOME, 'Desktop') : '';
  if (own) mkdirSync(own, { recursive: true });
  const ps = (own ? `$d=${q(own)}; ` : `$d=[Environment]::GetFolderPath('Desktop'); `) + `$w=New-Object -ComObject WScript.Shell; $s=$w.CreateShortcut((Join-Path $d 'Code Boss Setup.lnk')); `
    + `$s.TargetPath=${q(process.execPath)}; $s.Arguments=${q('"' + selfPath + '"')}; $s.WorkingDirectory=${q(path.dirname(selfPath))}; $s.WindowStyle=7; $s.Description='code_boss: chunks in, committed'; $s.Save()`;
  const r = spawnSync('powershell', ['-NoProfile', '-NonInteractive', '-Command', ps], { encoding: 'utf8', timeout: 20000, windowsHide: true });
  return r.status === 0;
}

const suGit = (dir, args) => spawnSync('git', args, { cwd: dir, encoding: 'utf8', windowsHide: true, maxBuffer: 64 * 1048576 });
const suSaid = (r) => String(`${r.stderr || ''}${r.stdout || ''}`).replace(/\/\/[^@/\s]+@/g, '//***@').trim();
/** Where chunks are committed: the source repository (the release window's, else the one users update from). */
const suSourceRepo = () => { const c = rsReadJson(rsCfgPath()); return String(c.sourceRepo || '').trim() || String(c.updateSource || '').trim(); };

/** The project folder's git, as the page shows it: { repo, branch, head, uncommitted, pushed } (no network). */
function suGitState(dir, branch) {
  if (!existsSync(path.join(dir, '.git'))) return { repo: false, branch };
  const head = String(suGit(dir, ['rev-parse', '-q', '--verify', 'HEAD']).stdout || '').trim();
  const on = String(suGit(dir, ['symbolic-ref', '-q', '--short', 'HEAD']).stdout || '').trim();
  const uncommitted = String(suGit(dir, ['status', '--porcelain']).stdout || '').split(/\r?\n/).filter(Boolean).length;
  const pushed = !!head && String(suGit(dir, ['rev-parse', '-q', '--verify', `refs/remotes/source/${branch}`]).stdout || '').trim() === head;
  return { repo: true, branch, on, head: head.slice(0, 10), uncommitted, pushed };
}

/**
 * The folder committed on `branch` and pushed. The first time, the folder becomes a checkout: its first commit goes on
 * the branch as GitLab has it (or, for a new branch, on main), so the history goes on; after that each commit is on
 * this folder's own last one. The push is never forced. { ok, said } or { ok: false, problem }.
 */
function suCommitAndPush({ dir, branch = 'main', message, push = true }) {
  const repo = suSourceRepo(), creds = rsReadJson(rsCredsPath());
  if (push && !repo) return { ok: false, problem: 'The repository is not set - fill it in under Source on GitLab, and Save.' };
  if (push && /^https?:/i.test(repo) && !(creds.user && creds.token)) return { ok: false, problem: 'A GitLab user and token are needed to push - fill them in under Source on GitLab, and Save.' };
  if (!/^[\w.][\w./-]*$/.test(branch) || branch.includes('..')) return { ok: false, problem: `"${branch}" is not a branch name.` };
  const remote = repo ? setupAuthedRemote(repo, creds) : '';
  if (!existsSync(path.join(dir, '.git'))) { const i = suGit(dir, ['init', '-q']); if (i.status !== 0) return { ok: false, problem: 'git init failed: ' + suSaid(i) }; }
  // (the chunks' record is this window's, never committed)
  const ex = path.join(dir, '.git', 'info', 'exclude');
  try { const t = existsSync(ex) ? readFileSync(ex, 'utf8') : ''; if (!/^\/?\.cb-sync\.json$/m.test(t)) { mkdirSync(path.dirname(ex), { recursive: true }); writeFileSync(ex, t + (t && !t.endsWith('\n') ? '\n' : '') + '/.cb-sync.json\n'); } } catch { /* said by git status */ }
  if (!(suGit(dir, ['config', 'user.email']).stdout || '').trim()) {
    suGit(dir, ['config', 'user.name', creds.user || 'code-boss']);
    suGit(dir, ['config', 'user.email', `${creds.user || 'code-boss'}@code-boss.local`]);
  }
  const has = (ref) => suGit(dir, ['rev-parse', '-q', '--verify', ref]).status === 0;
  if (!has(`refs/heads/${branch}`)) {
    // a branch new to this folder: on top of GitLab's (that branch, else main), so its history goes on
    let base = '';
    if (push) for (const b of [branch, 'main']) {
      const f = suGit(dir, ['fetch', '-q', '--no-tags', remote, `+refs/heads/${b}:refs/remotes/source/${b}`]);
      if (f.status === 0) { base = `refs/remotes/source/${b}`; break; }
      if (!/couldn't find remote ref|could not find remote ref/i.test(suSaid(f))) return { ok: false, problem: `GitLab's ${b} could not be fetched: ${suSaid(f).slice(0, 300)}` };
    }
    if (base) suGit(dir, ['update-ref', `refs/heads/${branch}`, base]);
  }
  suGit(dir, ['symbolic-ref', 'HEAD', `refs/heads/${branch}`]);
  suGit(dir, ['add', '-A']);
  const staged = suGit(dir, ['diff', '--cached', '--quiet']).status !== 0 || !has('HEAD');
  let said = 'nothing new to commit';
  if (staged) {
    const c = suGit(dir, ['commit', '-q', '-m', message]);
    if (c.status !== 0) return { ok: false, problem: 'the commit failed: ' + suSaid(c).slice(0, 300) };
    said = `committed on ${branch}: "${message}"`;
  }
  if (!push) return { ok: true, said: said + ' (not pushed)' };
  const p = suGit(dir, ['push', remote, `HEAD:refs/heads/${branch}`]);
  if (p.status !== 0) {
    return { ok: false, problem: /non-fast-forward|fetch first|rejected/i.test(suSaid(p))
      ? `${said}, but not pushed: GitLab's ${branch} has commits that did not come from these chunks (somebody committed there). Nothing of theirs is undone. Put a branch of your own in Branch, Save, and push again - then merge it on GitLab.`
      : `${said}, but the push failed: ${suSaid(p).slice(-300)}` };
  }
  suGit(dir, ['update-ref', `refs/remotes/source/${branch}`, 'HEAD']);
  return { ok: true, said: `${said}; pushed to ${branch}` };
}

/** The window. Resolves with an exit code when it is closed. `open` false: no Chrome (tests). */
function runSetupWindow({ selfPath, open = true, shortcut = true, onReady = () => {}, log = (m) => console.log(m) }) {
  const here = path.dirname(selfPath);
  const cfg = suReadJson(suCfgPath());
  let projectDir = cfg.projectDir || path.join(here, 'code_boss-project');
  const branchOf = () => String(suReadJson(suCfgPath()).branch || '').trim() || 'main';
  const token = randomBytes(18).toString('hex');
  let pending = null, lastSeen = Date.now(), server = null, idle = null;
  let shortcutSays = '', gitSays = null;   // (the last commit and push: what it said)
  if (shortcut && !existsSync(suShortcutPath())) shortcutSays = suMakeShortcut(selfPath) ? 'The desktop shortcut "Code Boss Setup" was made - it opens this window.' : '';

  // (the folder looked at - every file hashed - when it changed here, and otherwise every 20 s, not at every poll)
  let scanned = null, gitState = null;
  const rescan = () => { scanned = null; gitState = null; };
  let lastError = null;   // (the last failure of choosing or starting the folder: shown until one of them goes right)
  const commit = (message) => {
    const r = suCommitAndPush({ dir: projectDir, branch: branchOf(), message });
    gitSays = r.ok ? { ok: true, text: r.said } : { ok: false, text: r.problem };
    suLog(`commit: ${gitSays.text}`); gitState = null;
    return r;
  };
  const view = () => {
    const rec = existsSync(projectDir) ? ssReadRecord(projectDir) : null;
    let clean = null;
    if (rec) {
      if (!scanned || scanned.dir !== projectDir || Date.now() - scanned.at > 20000) { const s = ssScan(projectDir, rec); scanned = { dir: projectDir, at: Date.now(), clean: { missing: s.missing.length, changed: s.changed.length, examples: [...s.missing, ...s.changed].slice(0, 6) } }; }
      clean = scanned.clean;
      if (!gitState || Date.now() - gitState.at > 5000) gitState = { at: Date.now(), state: suGitState(projectDir, branchOf()) };
    }
    const c = rsReadJson(rsCfgPath()), creds = rsReadJson(rsCredsPath());
    return {
      projectDir, started: !!rec, damaged: !rec && existsSync(projectDir) && ssRecordState(projectDir) === 'damaged', chunk: rec ? rec.chunk || 0 : null, left: rec ? rec.left ?? null : null, files: rec ? Object.keys(rec.files).length : 0,
      hash: rec ? ssTreeHash(rec.files).slice(0, 8) : '', from: rec ? rec.from || '' : '', clean,
      setupGuess: path.join(here, 'code-boss-setup.mjs'),
      lastError: lastError && (lastError.where === '/api/start' || lastError.where === '/api/project') ? lastError.error : null, logPath: suLogPath(),
      pending: pending ? { number: pending.number, files: pending.files.length, left: pending.left ?? null } : null,
      shortcutSays,
      source: { repo: suSourceRepo(), updateSource: c.updateSource || '', separate: !!String(c.sourceRepo || '').trim(), glUser: creds.user || '', hasToken: !!creds.token, branch: branchOf() },
      git: rec && gitState ? gitState.state : null, gitSays,
      releaseWindow: existsSync(path.join(projectDir, 'scripts', 'release-window.mjs')),
    };
  };

  return new Promise((resolve) => {
    const finish = () => { clearInterval(idle); try { server.close(); server.closeAllConnections?.(); } catch { /* closed */ } resolve(0); };
    server = http.createServer((req, res) => {
      const send = (code, type, text) => { res.writeHead(code, { 'Content-Type': type, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' }); res.end(text); };
      const json = (code, v) => send(code, 'application/json; charset=utf-8', JSON.stringify(v));
      const port = server.address().port;
      if (req.headers.host !== `127.0.0.1:${port}` && req.headers.host !== `localhost:${port}`) return send(403, 'text/plain', 'this address is not the setup window\'s own');
      const u = new URL(req.url, `http://127.0.0.1:${port}`);
      if (u.pathname === '/' && req.method === 'GET') {
        if (u.searchParams.get('t') !== token) return send(403, 'text/plain', 'Open the setup window from its shortcut: this page needs the address it opens.');
        return send(200, 'text/html; charset=utf-8', SU_PAGE.replace('__CB_TOKEN__', token));
      }
      if (!u.pathname.startsWith('/api/')) return send(404, 'text/plain', 'not found');
      if (req.headers['x-cb-token'] !== token) return json(403, { ok: false, error: 'this request does not carry the setup window\'s token' });
      lastSeen = Date.now();
      if (u.pathname === '/api/state' && req.method === 'GET') return json(200, view());
      let body = '';
      req.on('data', (d) => { body += d; if (body.length > 64 * 1048576) req.destroy(); });
      req.on('end', () => {
        let b = {}; try { b = body ? JSON.parse(body) : {}; } catch { return json(400, { ok: false, error: 'not JSON' }); }
        const fail = (error) => { suLog(`${u.pathname}: ${error}`); lastError = { where: u.pathname, error }; return json(200, { ...view(), ok: false, error, logPath: suLogPath() }); };
        try {
          if (u.pathname === '/api/project' && req.method === 'POST') {
            const p = String(b.path || '').trim().replace(/^"|"$/g, '');
            if (!p) return fail('Name the project folder.');
            projectDir = path.resolve(p); pending = null; rescan(); lastError = null; gitSays = null;
            suWriteJson(suCfgPath(), { ...suReadJson(suCfgPath()), projectDir });
            return json(200, view());
          }
          if (u.pathname === '/api/start' && req.method === 'POST') {
            const setupPath = path.resolve(String(b.setup || '').trim().replace(/^"|"$/g, ''));
            if (existsSync(projectDir) && ssReadRecord(projectDir)) return fail('The project folder is started already.');
            // (a record that is there and cannot be read: starting again on it would lose what the folder holds)
            if (existsSync(projectDir) && ssRecordState(projectDir) === 'damaged') return fail('The record of this folder (.cb-sync.json) is damaged. Start a new project folder in an empty folder - Use this folder with a new name - and apply the chunks to it from the first.');
            if (!existsSync(setupPath)) return fail(`There is no file at ${setupPath}.`);
            if (!spEmbeddedOf(readFileSync(setupPath, 'utf8'))) return fail(`${setupPath} carries no source - is it code-boss-setup.mjs?`);
            ssStartFromSetup(projectDir, setupPath); rescan(); lastError = null;
            suWriteJson(suCfgPath(), { ...suReadJson(suCfgPath()), projectDir });
            return json(200, view());
          }
          if (u.pathname === '/api/check' && req.method === 'POST') {
            pending = null;
            const c = ssChunkFrom(String(b.text || ''));
            if (c.problem) return fail(`Not applied: ${c.problem}.`);
            const plan = ssPlan(projectDir, c.chunk);
            if (plan.problems) return fail('Not applied: ' + plan.problems.join('; '));
            pending = c.chunk;
            return json(200, view());
          }
          if (u.pathname === '/api/apply' && req.method === 'POST') {
            if (!pending) return fail('Paste a chunk and check it first.');
            const number = pending.number;
            const r = ssApply(projectDir, pending);
            pending = null; rescan();
            if (!r.ok) return fail('Not applied: ' + r.problems.join('; '));
            // each chunk, one commit on the branch, pushed
            commit(`Chunk ${number}`);
            return json(200, { ...view(), applied: r.written });
          }
          if (u.pathname === '/api/commit' && req.method === 'POST') {
            const rec = ssReadRecord(projectDir);
            if (!rec) return fail('Start the project folder first.');
            commit(rec.chunk ? `Chunk ${rec.chunk}` : `Started from the ${rec.from || 'setup file'}`);
            return json(200, view());
          }
          if (u.pathname === '/api/source' && req.method === 'POST') {
            relSaveSettings({ ...(typeof b.updateSource === 'string' ? { updateSource: b.updateSource } : {}), glUser: b.glUser, glToken: b.glToken });
            const br = String(b.branch || '').trim() || 'main';
            if (!/^[\w.][\w./-]*$/.test(br) || br.includes('..')) return fail(`"${br}" is not a branch name.`);
            suWriteJson(suCfgPath(), { ...suReadJson(suCfgPath()), branch: br });
            gitState = null;
            return json(200, view());
          }
          if (u.pathname === '/api/release-window' && req.method === 'POST') {
            const entry = path.join(projectDir, 'scripts', 'release-window.mjs');
            if (!existsSync(entry)) return fail('The project folder has no scripts/release-window.mjs yet - it comes with a chunk.');
            spawn(process.execPath, [entry], { cwd: projectDir, detached: true, stdio: 'ignore', windowsHide: true }).unref();
            return json(200, view());
          }
          if (u.pathname === '/api/shortcut' && req.method === 'POST') {
            shortcutSays = suMakeShortcut(selfPath) ? 'The desktop shortcut "Code Boss Setup" was made.' : 'The shortcut could not be made.';
            return json(200, view());
          }
          if (u.pathname === '/api/close' && req.method === 'POST') { json(200, { ok: true }); setTimeout(finish, 100); return; }
        } catch (e) { return fail(e.message); }
        return json(404, { ok: false, error: `no such thing: ${req.method} ${u.pathname}` });
      });
    });
    server.on('error', (e) => { log(`setup window: could not be served - ${e.message}`); resolve(1); });
    server.listen(0, '127.0.0.1', () => {
      const url = `http://127.0.0.1:${server.address().port}/?t=${token}`;
      onReady({ url });
      if (open && !suOpenWindow(url)) log(`setup window: Chrome was not found - open this address in a browser: ${url}`);
      else log(`setup window: open (${url.replace(/\?t=.*/, '')}). Close it, or press Ctrl+C here, when you are done.`);
      idle = setInterval(() => { if (Date.now() - lastSeen > 10 * 60 * 1000) { log('setup window: closed (nothing has asked for ten minutes).'); finish(); } }, 30000);
      if (typeof idle.unref === 'function' && !open) idle.unref();
    });
  });
}

const SU_PAGE = String.raw`<!doctype html><html><head><meta charset="utf-8"><title>code_boss setup</title>
<style>
:root{--bg:#0f0d0c;--panel:#191614;--panel-alt:#1e1b18;--fg:#f4eee8;--muted:#c0b5a8;--border:#3b3530;--cn-border:#2a2622;--accent:#ffa95c;--accent-rgb:255,169,92;--accent-hover:#ffbf7b;--accent-fg:#170f08;--err:#f15d87;--ok:#8fbf72;--code-bg:#13110f;--accent-ring:inset 0 0 0 1px var(--accent);
--mono:ui-monospace,"SF Mono","Cascadia Code","JetBrains Mono",Menlo,Consolas,"DejaVu Sans Mono",monospace}
*{box-sizing:border-box;font-variant-ligatures:none}body{margin:0;background:var(--bg);color:var(--fg);font:13.5px/1.55 var(--mono)}
main{max-width:900px;margin:0 auto;padding:18px 22px 40px}h1{font-size:15px;font-weight:700;color:var(--accent);margin:0 0 4px}
h2{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);margin:22px 0 8px;border-bottom:1px solid var(--border);padding-bottom:5px}
.sub{color:var(--muted);font-size:12px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:8px}
input[type=text],input[type=password],textarea{background:var(--panel-alt);color:var(--fg);border:1px solid var(--border);border-radius:5px;padding:5px 8px;font:12px/1.4 var(--mono)}
input[type=text]{flex:1;min-width:0}textarea{width:100%;resize:vertical}input:focus,textarea:focus{outline:none;border-color:var(--accent);box-shadow:var(--accent-ring)}
button{background:var(--panel);color:var(--fg);border:1px solid var(--border);border-radius:5px;padding:5px 12px;font:inherit;font-size:12px;font-weight:500;line-height:16px;cursor:pointer}button:hover:not(:disabled){border-color:var(--accent);color:var(--accent);box-shadow:var(--accent-ring)}
button.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-fg);font-weight:600}button.primary:hover:not(:disabled){background:var(--accent-hover);border-color:var(--accent-hover);color:var(--accent-fg)}
button:disabled{opacity:.45;cursor:default}
.err{color:var(--err)}.okc{color:var(--ok)}.hide{display:none}
label.f{display:grid;grid-template-columns:150px 1fr;gap:12px;align-items:center;margin:6px 0;font-size:12px}
</style></head><body><main>
<h1>code_boss setup</h1>
<div class="sub" id="shortcutSays"></div>
<h2>The project</h2>
<div class="row"><input type="text" id="project" spellcheck="false"><button id="projectUse">Use this folder</button></div>
<div class="sub" id="projectSays" style="margin-top:6px"></div>
<div id="startSec" class="hide"><div class="sub" style="margin-top:8px">The folder is started once, from the setup file this box has now:</div>
<div class="row"><input type="text" id="setupFile" spellcheck="false"><button class="primary" id="start">Start the folder from it</button></div></div>
<div id="chunkSec" class="hide"><h2>A chunk</h2>
<textarea id="text" rows="7" spellcheck="false" placeholder="Paste a chunk here - all of code-boss-chunk-NNN.txt"></textarea>
<div class="row"><button id="check">Check it</button><button class="primary" id="apply" disabled>Apply it</button><span class="sub" id="says"></span></div>
<div class="sub" style="margin-top:6px">Each chunk applied is committed on the branch below and pushed.</div></div>
<div id="srcSec" class="hide"><h2>Source on GitLab</h2>
<label class="f">Repository <input type="text" id="updateSource" spellcheck="false" placeholder="https://gitlab.example.mil/group/code_boss"></label>
<div class="sub" id="repoNote"></div>
<label class="f">GitLab user <input type="text" id="glUser" spellcheck="false"></label>
<label class="f">GitLab token <input type="password" id="glToken"></label>
<label class="f">Branch <input type="text" id="branch" spellcheck="false" placeholder="main"></label>
<div class="row"><button id="save">Save</button><span class="sub" id="saved"></span></div>
<div class="sub" id="gitLine" style="margin-top:8px"></div>
<div class="row"><button id="commit">Commit and push</button><span class="sub" id="gitSays"></span></div></div>
<h2>Releases</h2>
<div class="sub">Releases are made in the release window, from this folder: code_boss and its container image, one build.</div>
<div class="row"><button class="primary" id="relWin">Open the release window</button><span class="sub" id="relSays"></span></div>
<div class="row" style="margin-top:18px"><button id="shortcut">Make the desktop shortcut</button><button id="close">Close</button></div>
</main><script>
const T='__CB_TOKEN__';
const api=(p,b)=>fetch(p,{method:b?'POST':'GET',headers:{'x-cb-token':T,'content-type':'application/json'},body:b?JSON.stringify(b):undefined}).then(r=>r.json());
const $=(id)=>document.getElementById(id);
const esc=(s)=>String(s==null?'':s).replace(/[&<>"]/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]);
let editing=false,editingSetup=false,dirty=false;
function fill(s){
  if(!editing)$('project').value=s.projectDir;
  if(!editingSetup&&!$('setupFile').value)$('setupFile').value=s.setupGuess;
  $('shortcutSays').textContent=s.shortcutSays||'';
  $('startSec').classList.toggle('hide',s.started);$('chunkSec').classList.toggle('hide',!s.started);$('srcSec').classList.toggle('hide',!s.started);
  $('projectSays').innerHTML=s.lastError?'<span class="err">'+esc(s.lastError)+'</span><br><span class="sub">(it is also in '+esc(s.logPath)+')</span>':s.damaged?'<span class="err">Its record (.cb-sync.json) is damaged, so what is in it cannot be told. Use a new, empty folder and start it from your setup file; then apply the chunks from the first.</span>':!s.started?'Not started yet.':(s.clean&&(s.clean.missing||s.clean.changed)?'<span class="err">Changed outside the chunks: '+esc(s.clean.examples.join(', '))+'. If an apply was cut off, paste the same chunk again - it finishes it.</span>':
    (s.chunk?'Chunk <b>'+esc(s.chunk)+'</b> is the last one applied':'Started from the '+esc(s.from)+'; no chunk yet')+' - '+esc(s.files)+' files, folder '+esc(s.hash)+'.'+(s.left===0?' <span class="okc">It matches the development box.</span>':s.left?' '+esc(s.left)+' files still to come.':''));
  const src=s.source;
  if(!dirty){$('updateSource').value=src.separate?src.repo:src.updateSource;$('updateSource').disabled=src.separate;$('glUser').value=src.glUser;$('glToken').placeholder=src.hasToken?'(saved - type a new one to replace it)':'';$('branch').value=src.branch;}
  $('repoNote').textContent=src.separate?'(the source repository the release window has - change it there)':'';
  const g=s.git;
  $('gitLine').innerHTML=!g?'':!g.repo?'Not committed yet: the first commit makes this folder a checkout of '+esc(src.branch)+'.':'On <b>'+esc(g.on||g.branch)+'</b> at '+esc(g.head||'(no commit)')+(g.uncommitted?' - <span class="err">'+esc(g.uncommitted)+' file(s) not committed</span>':' - all committed')+(g.head&&!g.uncommitted?(g.pushed?', <span class="okc">pushed</span>':', <span class="err">not pushed</span>'):'')+'.';
  $('gitSays').innerHTML=s.gitSays?(s.gitSays.ok?'<span class="okc">'+esc(s.gitSays.text)+'</span>':'<span class="err">'+esc(s.gitSays.text)+'</span>'):'';
  $('apply').disabled=!s.pending;
  $('relWin').disabled=!s.releaseWindow;$('relSays').textContent=s.releaseWindow?'':'(it comes with a chunk)';
  if(s.pending)$('says').innerHTML='<span class="okc">Chunk '+esc(s.pending.number)+': '+esc(s.pending.files)+' files, and it goes on this folder.</span>';
}
const said=(r)=>{fill(r);if(r.ok===false)$('says').innerHTML='<span class="err">'+esc(r.error)+'</span>';};
$('project').addEventListener('input',()=>{editing=true;});$('setupFile').addEventListener('input',()=>{editingSetup=true;});
$('projectUse').onclick=async()=>{const r=await api('/api/project',{path:$('project').value});editing=false;fill(r);if(r.ok===false)$('projectSays').innerHTML='<span class="err">'+esc(r.error)+'</span>';};
$('start').onclick=async()=>{$('projectSays').textContent='Starting...';const r=await api('/api/start',{setup:$('setupFile').value});fill(r);if(r.ok===false)$('projectSays').innerHTML='<span class="err">'+esc(r.error)+'</span>';};
$('check').onclick=async()=>{const text=$('text').value;if(!text.trim()){$('says').textContent='Paste the chunk first.';return;}$('says').textContent='Checking...';said(await api('/api/check',{text}));};
$('apply').onclick=async()=>{$('says').textContent='Applying, committing and pushing...';const r=await api('/api/apply',{});if(r.ok!==false){$('text').value='';$('says').innerHTML='<span class="okc">Applied: '+esc(r.applied)+' files written.</span>';fill(r);}else said(r);};
async function save(){const r=await api('/api/source',{updateSource:$('updateSource').disabled?undefined:$('updateSource').value,glUser:$('glUser').value,glToken:$('glToken').value,branch:$('branch').value});if(r.ok===false){$('saved').innerHTML='<span class="err">'+esc(r.error)+'</span>';return false;}dirty=false;$('glToken').value='';fill(r);$('saved').textContent='Saved.';setTimeout(()=>{if(!dirty)$('saved').textContent='';},2500);return true;}
for(const id of ['updateSource','glUser','glToken','branch'])$(id).addEventListener('input',()=>{dirty=true;$('saved').textContent='Not saved yet.';});
$('save').onclick=save;
$('commit').onclick=async()=>{if(dirty&&!(await save()))return;$('gitSays').textContent='Committing and pushing...';const r=await api('/api/commit',{});fill(r);if(r.ok===false)$('gitSays').innerHTML='<span class="err">'+esc(r.error)+'</span>';};
$('relWin').onclick=async()=>{const r=await api('/api/release-window',{});fill(r);$('relSays').innerHTML=r.ok===false?'<span class="err">'+esc(r.error)+'</span>':'Opening - it is its own window.';};
$('shortcut').onclick=async()=>{fill(await api('/api/shortcut',{}));};
$('close').onclick=async()=>{const r=await api('/api/close',{});if(r.ok)document.body.innerHTML='<main><h1>Closed.</h1><div class="sub">Open it again from the "Code Boss Setup" shortcut.</div></main>';};
async function tick(){try{fill(await api('/api/state'));}catch{}}
tick();setInterval(tick,1500);
</script></body></html>`;

(async () => {
  const self = fileURLToPath(import.meta.url);
  const a = process.argv.slice(2);
  const val = (f) => { const i = a.indexOf(f); return i >= 0 ? a[i + 1] : null; };
  console.log('[code_boss] setup window, build ' + BUILD_VERSION);
  process.exit(await runSetupWindow({ selfPath: self }));
})();
